function pic(p) {
  if (!p) return '';
  if (p.charAt(0) === '~') {
    var k = p.indexOf('~', 1);
    return PFX[parseInt(p.slice(1, k), 10)] + p.slice(k + 1);
  }
  if (p.indexOf('http') === 0) return p;
  return 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p' + p + '.jpg' + SUF;
}

function pageOf(arr, pg) {
  var lim = 20;
  var page = parseInt(pg || '1', 10) || 1;
  var st = (page - 1) * lim;
  var sl = arr.slice(st, st + lim);
  var out = [];
  for (var i = 0; i < sl.length; i++) {
    var m = sl[i];
    out.push({
      vod_id: 'msearch:' + m.n,
      vod_name: m.n,
      vod_pic: pic(m.p),
      vod_remarks: (st + i + 1) + (m.y ? '. ' + m.y : '')
    });
  }
  return JSON.stringify({ page: page, pagecount: page + 1, limit: lim, total: arr.length, list: out });
}

